<section class="pr560-section"><div class="pr560-shell" style="max-width:1120px"><div class="pr560-head"><div><span>PROPERTY OWNER / AGENT</span><h2><?=$p?'Edit property':'Post a property'?></h2><p>Add complete details, photos and map location. <?=setting_bool('property_v560_require_approval',true)?'New user listings are reviewed before going live.':''?></p></div><a href="/my-properties.php">My Property →</a></div><?php if($error):?><div class="pr560-alert err"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="pr560-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><section class="pr560-panel"><h3>Basic listing</h3><div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px"><label>Property title<input name="title" required value="<?=e($p['title']??'')?>" placeholder="5 Marla House for Sale in..."></label><label>Purpose<select name="purpose"><?php foreach(pr560_purposes() as $k=>$v):?><option value="<?=e($k)?>" <?=($p['purpose']??'sale')===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Property type<select name="property_type"><?php foreach(pr560_types() as $t):?><option <?=($p['property_type']??'House')===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></label></div><label style="margin-top:10px">Short summary<input name="summary" value="<?=e($p['summary']??'')?>" placeholder="Family home near main road, ready possession..."></label><label style="margin-top:10px">Full description<textarea name="description" rows="7" required><?=e($p['description']??'')?></textarea></label></section>
<section class="pr560-panel"><h3>Price & size</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px"><label>Price (PKR)<input type="number" min="0" name="price_value" value="<?=e((string)($p['price_value']??''))?>"></label><label>Price period<select name="price_period"><option value="">One-time</option><?php foreach(['month'=>'Per month','year'=>'Per year'] as $k=>$v):?><option value="<?=$k?>" <?=($p['price_period']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Area<input type="number" min="0" step="0.01" name="area_value" value="<?=e((string)($p['area_value']??''))?>"></label><label>Area unit<select name="area_unit"><?php foreach(pr560_area_units() as $u):?><option <?=($p['area_unit']??'Marla')===$u?'selected':''?>><?=e($u)?></option><?php endforeach;?></select></label></div><div style="display:flex;gap:18px;margin-top:12px;flex-wrap:wrap"><label><input style="width:auto" type="checkbox" name="price_negotiable" value="1" <?=!empty($p['price_negotiable'])?'checked':''?>> Price negotiable</label><label><input style="width:auto" type="checkbox" name="price_on_call" value="1" <?=!empty($p['price_on_call'])?'checked':''?>> Price on call</label><label><input style="width:auto" type="checkbox" name="installment_available" value="1" <?=!empty($p['installment_available'])?'checked':''?>> Installments available</label></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:10px"><label>Down payment<input type="number" name="down_payment" value="<?=e((string)($p['down_payment']??0))?>"></label><label>Monthly installment<input type="number" name="monthly_installment" value="<?=e((string)($p['monthly_installment']??0))?>"></label></div></section>
<section class="pr560-panel"><h3>Rooms & specifications</h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px"><label>Bedrooms<input type="number" min="0" name="bedrooms" value="<?=e((string)($p['bedrooms']??0))?>"></label><label>Bathrooms<input type="number" min="0" name="bathrooms" value="<?=e((string)($p['bathrooms']??0))?>"></label><label>Parking spaces<input type="number" min="0" name="parking_spaces" value="<?=e((string)($p['parking_spaces']??0))?>"></label><label>Year built<input type="number" min="0" max="<?=date('Y')+5?>" name="year_built" value="<?=e((string)($p['year_built']??0))?>"></label><label>Floor no.<input type="number" min="0" name="floor_no" value="<?=e((string)($p['floor_no']??0))?>"></label><label>Total floors<input type="number" min="0" name="total_floors" value="<?=e((string)($p['total_floors']??0))?>"></label><label>Furnishing<select name="furnishing"><option value="">Not specified</option><?php foreach(['Unfurnished','Semi Furnished','Furnished'] as $v):?><option <?=($p['furnishing']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Condition<select name="condition_status"><option value="">Not specified</option><?php foreach(['Brand New','Excellent','Good','Needs Renovation','Under Construction'] as $v):?><option <?=($p['condition_status']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div></section>
